assign SaveStateBus_Dout = SaveStateBus_wired_or[0] | SaveStateBus_wired_or[1] | SaveStateBus_wired_or[2] | SaveStateBus_wired_or[3] | SaveStateBus_wired_or[6] | SaveStateBus_wired_or[7] | SaveStateBus_wired_or[8] | SaveStateBus_wired_or[9] | SaveStateBus_wired_or[12];
assign Savestate_MAPRAMReadData = 8'd0;

